'use strict';

const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const [p, s, r] = input;

const MOD = 998244353;
const BASE = 32768;

function mulMod(a, b) {
    const high = Math.floor(b / BASE);
    const low = b - high * BASE;
    return (a * low + (a * high % MOD) * BASE) % MOD;
}

function modPow(base, exp) {
    let result = 1;
    while (exp > 0) {
        if (exp % 2 === 1) result = mulMod(result, base);
        base = mulMod(base, base);
        exp = Math.floor(exp / 2);
    }
    return result;
}

const maxN = s + p;
const width = p + 1;
const combinations = new Uint32Array((maxN + 1) * width);

combinations[0] = 1;

for (let n = 1; n <= maxN; n++) {
    const row = n * width;
    const previous = (n - 1) * width;
    combinations[row] = 1;

    const limit = Math.min(n, p);
    for (let k = 1; k <= limit; k++) {
        let value = combinations[previous + k] + combinations[previous + k - 1];
        if (value >= MOD) value -= MOD;
        combinations[row + k] = value;
    }
}

function choose(n, k) {
    if (n < 0 || k < 0 || k > n || k > p) return 0;
    return combinations[n * width + k];
}

const inverses = new Array(p + 1);
for (let i = 1; i <= p; i++) {
    inverses[i] = modPow(i, MOD - 2);
}

const opponents = p - 1;
let numerator = 0;

for (let k = 0; k < opponents; k++) {
    const remaining = opponents - k;
    const degree = remaining - 1;
    const firstCoefficient = mulMod(
        choose(opponents, k),
        inverses[k + 1]
    );

    for (let j = 0; j <= remaining; j++) {
        const multiplier = k + j + 1;
        const maxScore = Math.floor(s / multiplier);

        if (r > maxScore) continue;

        const coefficient = mulMod(
            firstCoefficient,
            choose(remaining, j)
        );

        for (let score = r; score <= maxScore; score++) {
            const top = s - multiplier * score + degree;
            const ways = choose(top, degree);
            const term = mulMod(coefficient, ways);

            if (j % 2 === 0) {
                numerator += term;
                if (numerator >= MOD) numerator -= MOD;
            } else {
                numerator -= term;
                if (numerator < 0) numerator += MOD;
            }
        }
    }
}

if (s % p === 0 && s / p >= r) {
    numerator += inverses[p];
    if (numerator >= MOD) numerator -= MOD;
}

const totalStates = choose(s - r + p - 1, p - 1);
const answer = mulMod(numerator, modPow(totalStates, MOD - 2));

console.log(answer.toString());

