const fs = require('fs');

const [p, s, r] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const MOD = 998244353;
const MOD_BI = 998244353n;

const maxN = s + p - 1;
const limit = Math.max(maxN, p);
const kTarget = p - 1;

const dp = new Array(p + 1).fill(0);
const combK = new Array(maxN + 1).fill(0);
let chooseP = null;

dp[0] = 1;
if (kTarget === 0) combK[0] = 1;

for (let n = 1; n <= limit; n++) {
    for (let k = Math.min(n, p); k >= 1; k--) {
        let value = dp[k] + dp[k - 1];
        if (value >= MOD) value -= MOD;
        dp[k] = value;
    }

    if (n <= maxN) combK[n] = dp[kTarget];
    if (n === p) chooseP = dp.slice();
}

const total = combK[s + p - 1];
const validHasanStates = combK[s - r + p - 1];

let bounded = 0n;

if (r > 0) {
    const maxJ = Math.min(p, Math.floor(s / r));

    for (let j = 0; j <= maxJ; j++) {
        const n = s - j * r + p - 1;
        const term =
            (BigInt(chooseP[j]) * BigInt(combK[n])) % MOD_BI;

        bounded += (j % 2 === 0) ? term : -term;
        bounded %= MOD_BI;
    }

    if (bounded < 0n) bounded += MOD_BI;
}

let favorable = (BigInt(total) - bounded) % MOD_BI;
if (favorable < 0n) favorable += MOD_BI;

const denominator =
    (BigInt(p) * BigInt(validHasanStates)) % MOD_BI;

function modPow(base, exponent) {
    let result = 1n;
    while (exponent > 0n) {
        if (exponent & 1n) result = (result * base) % MOD_BI;
        base = (base * base) % MOD_BI;
        exponent >>= 1n;
    }
    return result;
}

const answer =
    (favorable * modPow(denominator, MOD_BI - 2n)) % MOD_BI;

console.log(answer.toString());
